(()=>{
const nav=document.querySelector('.nav');if(!nav)return;
const host=document.createElement('div');host.className='account-menu-control';
const button=document.createElement('button');button.type='button';button.className='account-menu-toggle';button.setAttribute('aria-label','معلومات الحساب');button.title='حسابي';button.setAttribute('aria-expanded','false');button.setAttribute('aria-controls','account-menu-panel');button.innerHTML='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/></svg>';host.append(button);
const actions=nav.querySelector('.nav-actions');if(actions)actions.prepend(host);else nav.append(host);
const panel=document.createElement('section');panel.id='account-menu-panel';panel.className='account-menu-panel';panel.hidden=true;panel.setAttribute('aria-label','معلومات الحساب');
const heading=document.createElement('small');heading.textContent='حسابك في أويس تك';const name=document.createElement('strong');name.dir='auto';const phone=document.createElement('span');phone.dir='ltr';phone.className='account-menu-phone';const link=document.createElement('a');link.className='account-menu-link';const logout=document.createElement('button');logout.type='button';logout.className='account-menu-logout';logout.textContent='تسجيل الخروج';const feedback=document.createElement('p');feedback.setAttribute('role','status');panel.append(heading,name,phone,link,logout,feedback);document.body.append(panel);
function close(focus=false){panel.hidden=true;button.setAttribute('aria-expanded','false');if(focus)button.focus()}
function position(){const rect=button.getBoundingClientRect(),width=Math.min(300,innerWidth-24);panel.style.width=width+'px';panel.style.left=Math.max(12,Math.min(innerWidth-width-12,rect.right-width))+'px';panel.style.top=Math.min(rect.bottom+10,innerHeight-200)+'px'}
button.onclick=()=>{if(!panel.hidden){close();return}panel.hidden=false;position();button.setAttribute('aria-expanded','true');link.focus()};
document.addEventListener('click',event=>{if(!panel.hidden&&!panel.contains(event.target)&&!host.contains(event.target))close()});document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!panel.hidden){event.preventDefault();close(true)}});window.addEventListener('resize',()=>{if(!panel.hidden)position()});window.addEventListener('scroll',()=>close(),{passive:true});
function render(user){name.textContent=user?user.full_name:'أهلًا بك';phone.textContent=user?.phone||'';phone.hidden=!user?.phone;link.href=user?(user.role==='admin'?'/admin':'/account'):'/account?mode=login';link.textContent=user?(user.role==='admin'?'فتح لوحة الإدارة':'فتح حسابي وطلباتي'):'تسجيل الدخول أو إنشاء حساب';logout.hidden=!user;logout.disabled=false;button.setAttribute('aria-label',user?'معلومات حساب '+user.full_name:'تسجيل الدخول ومعلومات الحساب');feedback.textContent=''}
async function refresh(){try{const r=await fetch('/api/auth/me',{cache:'no-store'});if(r.status===401){render(null);return}if(!r.ok)throw Error();render((await r.json()).user)}catch{feedback.textContent='تعذر التحقق من الجلسة؛ حدّث الصفحة.'}}
logout.onclick=async()=>{if(logout.disabled)return;logout.disabled=true;try{const r=await fetch('/api/auth/logout',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});if(!r.ok)throw Error();render(null);location.assign('/')}catch{feedback.textContent='تعذر تسجيل الخروج، حاول مجددًا.';logout.disabled=false}};
window.addEventListener('oways:session',event=>{render(event.detail);close()});window.addEventListener('pageshow',refresh);render(null);
})();